return function(ctx,text,default,callback) local b=Instance.new("TextButton",ctx.Parent);b.Name="Keybind";b.Size=UDim2.new(1,0,0,38);b.BackgroundColor3=ctx.Theme:Get("SurfaceAlt");b.TextColor3=ctx.Theme:Get("Text");b.Text=(text or "Keybind")..": "..tostring(default and default.Name or "None");b.Font=Enum.Font.Gotham;b.TextSize=14;Instance.new("UICorner",b).CornerRadius=UDim.new(0,10);local c=Control.new(b,ctx,default);local listening=false;ctx.Input:BindPress(b,function()listening=true;b.Text=(text or "Keybind")..": ..."end);ctx.Maid:Give(UIS.InputBegan:Connect(function(i,g)if listening and not g then local key=i.KeyCode~=Enum.KeyCode.Unknown and i.KeyCode or i.UserInputType;c:SetValue(key);b.Text=(text or "Keybind")..": "..key.Name;listening=false;if callback then callback(key)end end end));return c end
